-- Harbor Microfinance Bank (Finance, amounts in naira)
-- Generated by gen_datasets.py with a fixed seed. Fictional data.

DROP TABLE IF EXISTS repayments; DROP TABLE IF EXISTS loans; DROP TABLE IF EXISTS transactions; DROP TABLE IF EXISTS accounts;
DROP TABLE IF EXISTS customers; DROP TABLE IF EXISTS employees; DROP TABLE IF EXISTS branches;
CREATE TABLE branches (branch_id INT PRIMARY KEY, branch_name VARCHAR(60) COLLATE NOCASE, city VARCHAR(60) COLLATE NOCASE, opened_date DATE, manager_id INT);
CREATE TABLE employees (employee_id INT PRIMARY KEY, branch_id INT REFERENCES branches(branch_id), first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, role VARCHAR(60) COLLATE NOCASE,
  manager_id INT REFERENCES employees(employee_id), hire_date DATE, salary DECIMAL(10,2));
CREATE TABLE customers (customer_id INT PRIMARY KEY, branch_id INT REFERENCES branches(branch_id), first_name VARCHAR(60) COLLATE NOCASE, last_name VARCHAR(60) COLLATE NOCASE, gender VARCHAR(60) COLLATE NOCASE,
  join_date DATE, segment VARCHAR(60) COLLATE NOCASE, credit_score INT, city VARCHAR(60) COLLATE NOCASE);
CREATE TABLE accounts (account_id INT PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), account_type VARCHAR(60) COLLATE NOCASE, opened_date DATE, status VARCHAR(60) COLLATE NOCASE);
CREATE TABLE transactions (txn_id INT PRIMARY KEY, account_id INT REFERENCES accounts(account_id), txn_date DATE, amount DECIMAL(12,2), direction VARCHAR(60) COLLATE NOCASE, channel VARCHAR(60) COLLATE NOCASE);
CREATE TABLE loans (loan_id INT PRIMARY KEY, customer_id INT REFERENCES customers(customer_id), officer_id INT REFERENCES employees(employee_id), product VARCHAR(60) COLLATE NOCASE,
  principal DECIMAL(12,2), interest_rate_pct DECIMAL(5,2), disbursed_date DATE, tenor_months INT, status VARCHAR(60) COLLATE NOCASE);
CREATE TABLE repayments (repayment_id INT PRIMARY KEY, loan_id INT REFERENCES loans(loan_id), due_date DATE, amount_due DECIMAL(12,2), paid_date DATE, amount_paid DECIMAL(12,2));







